WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT v.id, v.etapa, v.mensagem, v.nivel, v.criado_em FROM pedido_eventos v JOIN pedidos p ON p.pedido_id = v.pedido_id JOIN eu ON (eu.admin OR p.executivo_id = eu.executivo_id) WHERE v.pedido_id = :pedido_id ORDER BY v.id DESC LIMIT 200
